"""Auditable persistence model for drought and credit-score predictions."""

from __future__ import annotations

from datetime import date, datetime, timezone
from typing import Any, Optional

from sqlalchemy import Date, DateTime, Float, ForeignKey, Integer, JSON, String
from sqlalchemy.orm import Mapped, mapped_column, relationship

from backend.database.session import Base


class Prediction(Base):
    """A point-in-time outcome generated by the unchanged ML inference API."""

    __tablename__ = "predictions"

    id: Mapped[int] = mapped_column(Integer, primary_key=True, index=True)
    user_id: Mapped[Optional[int]] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"), index=True)
    farm_id: Mapped[Optional[int]] = mapped_column(ForeignKey("farms.id", ondelete="SET NULL"), index=True)
    latitude: Mapped[float] = mapped_column(Float, nullable=False)
    longitude: Mapped[float] = mapped_column(Float, nullable=False)
    start_date: Mapped[date] = mapped_column(Date, nullable=False)
    end_date: Mapped[date] = mapped_column(Date, nullable=False)
    prediction_date: Mapped[date] = mapped_column(Date, nullable=False)
    drought_index: Mapped[float] = mapped_column(Float, nullable=False)
    ndvi: Mapped[float] = mapped_column(Float, nullable=False)
    lst: Mapped[float] = mapped_column(Float, nullable=False)
    risk_classification: Mapped[str] = mapped_column(String(40), nullable=False)
    credit_score: Mapped[float] = mapped_column(Float, nullable=False)
    model_version: Mapped[Optional[str]] = mapped_column(String(80), nullable=True)
    climate: Mapped[Optional[dict[str, Any]]] = mapped_column(JSON, nullable=True)
    recommendations: Mapped[Optional[list[dict[str, str]]]] = mapped_column(JSON, nullable=True)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False
    )

    user: Mapped[Optional["User"]] = relationship(back_populates="predictions")
    farm: Mapped[Optional["Farm"]] = relationship(back_populates="predictions")
    reports: Mapped[list["Report"]] = relationship(back_populates="prediction")
